package hk.local.enginex7;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import java.lang.ref.WeakReference;

public final class MainActivity extends Activity {
 public static WeakReference<MainActivity> current=new WeakReference<>(null);private EngineService service;private PanelView panel;private boolean bound,askingOverlay;
 private final ServiceConnection connection=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){service=((EngineService.LocalBinder)b).get();bound=true;showPanel();if("permission".equals(getIntent().getAction()))permission();else if(Settings.canDrawOverlays(MainActivity.this)){service.showOverlay(false);if(service.hasOverlay())moveTaskToBack(true);}}public void onServiceDisconnected(ComponentName n){bound=false;}};
 @Override public void onCreate(Bundle state){super.onCreate(state);current=new WeakReference<>(this);getWindow().setStatusBarColor(PanelView.BG);getWindow().setNavigationBarColor(PanelView.BG);startForegroundService(new Intent(this,EngineService.class));bindService(new Intent(this,EngineService.class),connection,BIND_AUTO_CREATE);}
 private void showPanel(){panel=new PanelView(this,service,new EngineService.Host(){public void floating(){floatingPanel();}public void minimize(){if(Settings.canDrawOverlays(MainActivity.this)){service.showOverlay(true);moveTaskToBack(true);}else floatingPanel();}public void exit(){service.exit();}public void permission(){MainActivity.this.permission();}},false);setContentView(panel);}
 private void floatingPanel(){if(Settings.canDrawOverlays(this)){service.showOverlay(false);if(service.hasOverlay())moveTaskToBack(true);}else{askingOverlay=true;try{startActivityForResult(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())),21);}catch(Exception e){service.message=service.config.t("車機沒有浮窗授權頁；可先用主畫面。","Overlay permission page unavailable. Main screen remains usable.");askingOverlay=false;}}}
 private void permission(){if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},22);else{if(service!=null){service.message=service.config.t("定位已允許；按啟動引擎。","Location allowed. Press Start engine.");service.removeOverlay();showPanel();}}}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);if(service!=null&&"permission".equals(intent.getAction())){service.removeOverlay();permission();}}
 @Override public void onConfigurationChanged(android.content.res.Configuration c){super.onConfigurationChanged(c);if(service!=null){if(service.hasOverlay())service.showOverlay(service.minimized);else showPanel();}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==21){askingOverlay=false;if(service!=null&&Settings.canDrawOverlays(this)){service.showOverlay(false);if(service.hasOverlay())moveTaskToBack(true);}}}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(service!=null){service.message=checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED?service.config.t("定位已允許；按啟動引擎。","Location allowed. Press Start engine."):service.config.t("定位未允許；可選模擬駕駛試聲。","Location not allowed. Use simulation to try sounds.");showPanel();}}
 @Override public void onBackPressed(){if(panel!=null&&panel.back())return;if(service!=null&&Settings.canDrawOverlays(this))service.showOverlay(true);moveTaskToBack(true);}
 @Override protected void onStop(){super.onStop();if(service!=null&&!askingOverlay&&!isFinishing()&&Settings.canDrawOverlays(this)&&!service.hasOverlay())service.showOverlay(true);}
 @Override protected void onDestroy(){if(bound){unbindService(connection);bound=false;}if(current.get()==this)current.clear();super.onDestroy();}
}
